using R_Third = std::ratio<1, 3>;
using R_Half = std::ratio<1, 2>;

// Addition (1/3 + 1/2 = 5/6)
using Sum = std::ratio_add<R_Third, R_Half>;
static_assert(Sum::num == 5);
static_assert(Sum::den == 6);

// Multiplication (1/3 * 1/2 = 1/6)
using Product = std::ratio_multiply<R_Third, R_Half>;
static_assert(Product::num == 1);
static_assert(Product::den == 6);

// Simplification Check (10/12 reduces to 5/6)
using R_Complex = std::ratio<10, 12>;
static_assert(R_Complex::num == 5);
static_assert(R_Complex::den == 6);
